// Commit authorization v1 (Prompt 17B, D-127): the Dart derivation must
// produce exactly the challenge the server derives and verifies. Vector
// generated by functions/test/vectors/generate.mjs (TypeScript).
import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:flutter_test/flutter_test.dart';
import 'package:sirf_hum/security/messaging/commit_authorization.dart';

Uint8List _hex(String s) => Uint8List.fromList([
  for (var i = 0; i < s.length; i += 2)
    int.parse(s.substring(i, i + 2), radix: 16),
]);

String _toHex(List<int> b) =>
    b.map((x) => x.toRadixString(16).padLeft(2, '0')).join();

void main() {
  final v =
      jsonDecode(
            File(
              'functions/test/vectors/commit_authorization_v1.json',
            ).readAsStringSync(),
          )
          as Map<String, Object?>;

  List<AuthorizedWelcome> welcomes() => [
    for (final w in (v['welcomes']! as List).cast<Map<String, Object?>>())
      AuthorizedWelcome(
        targetDeviceId: _hex(w['targetDeviceIdHex']! as String),
        welcome: _hex(w['welcomeHex']! as String),
      ),
  ];

  Uint8List derive({List<AuthorizedWelcome>? with_, int? fromEpoch}) =>
      commitAuthorizationChallenge(
        nonce: _hex(v['nonceHex']! as String),
        accountId: v['accountId']! as String,
        deviceId: _hex(v['deviceIdHex']! as String),
        conversationId: _hex(v['conversationIdHex']! as String),
        fromEpoch: fromEpoch ?? v['fromEpoch']! as int,
        protocolVersion: v['protocolVersion']! as int,
        commit: _hex(v['commitHex']! as String),
        welcomes: with_ ?? welcomes(),
      );

  test('matches the server-generated golden vector', () {
    expect(_toHex(derive()), v['challengeHex']);
    expect(_toHex(derive(with_: const [])), v['challengeWithoutWelcomesHex']);
  });

  test('epochs and Welcome order are bound', () {
    expect(_toHex(derive(fromEpoch: 8)), isNot(v['challengeHex']));
    expect(
      _toHex(derive(with_: welcomes().reversed.toList())),
      isNot(v['challengeHex']),
    );
  });

  test('malformed inputs are refused', () {
    expect(
      () => commitAuthorizationChallenge(
        nonce: Uint8List(31),
        accountId: 'a',
        deviceId: Uint8List(16),
        conversationId: Uint8List(16),
        fromEpoch: 0,
        protocolVersion: 1,
        commit: Uint8List(1),
        welcomes: const [],
      ),
      throwsArgumentError,
    );
    expect(
      () => commitAuthorizationChallenge(
        nonce: Uint8List(32),
        accountId: 'a',
        deviceId: Uint8List(16),
        conversationId: Uint8List(16),
        fromEpoch: -1,
        protocolVersion: 1,
        commit: Uint8List(1),
        welcomes: const [],
      ),
      throwsArgumentError,
    );
  });
}
